INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kCNAIciwxHX', 4, '{"title":"第20201120条・刺腰痛篇第四十一","description":"<p>1、足太阳脉令人腰痛。引项脊尻背如重状。刺其郄中。太阳正经出血。春无见血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201120,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、足太阳脉令人腰痛。引项脊尻背如重状。刺其郄中。太阳正经出血。春无见血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('92Y9JJF6dv2', 4, '{"title":"第20201121条・刺腰痛篇第四十一","description":"<p>2、少阳令人腰痛。如以针刺其皮中。循循然不可以俯仰。不可以顾。刺少阳成骨之端出血。成骨在膝外廉之骨独起者。夏无见血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201121,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、少阳令人腰痛。如以针刺其皮中。循循然不可以俯仰。不可以顾。刺少阳成骨之端出血。成骨在膝外廉之骨独起者。夏无见血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K4I7vVUG9Ht', 4, '{"title":"第20201122条・刺腰痛篇第四十一","description":"<p>3、阳明令人腰痛。不可以顾。顾如有见者。善悲。刺阳明于䯒前三痏。上下和之出血。秋无见血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201122,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、阳明令人腰痛。不可以顾。顾如有见者。善悲。刺阳明于䯒前三痏。上下和之出血。秋无见血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DrNJd4JvVRG', 4, '{"title":"第20201123条・刺腰痛篇第四十一","description":"<p>4、足少阴令人腰痛。痛引脊内廉。刺少阴于内踝上二痏。春无见血。出血太多。不可复也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201123,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、足少阴令人腰痛。痛引脊内廉。刺少阴于内踝上二痏。春无见血。出血太多。不可复也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('S1EIjgNpdiq', 4, '{"title":"第20201124条・刺腰痛篇第四十一","description":"<p>5、厥阴之脉令人腰痛。腰中如张弓弩弦。刺厥阴之脉。在踵鱼腹之外。循之累累然。乃刺之。其病令人善言默默然不慧。刺之三痏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201124,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、厥阴之脉令人腰痛。腰中如张弓弩弦。刺厥阴之脉。在踵鱼腹之外。循之累累然。乃刺之。其病令人善言默默然不慧。刺之三痏。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qqSGBJifHN1', 4, '{"title":"第20201125条・刺腰痛篇第四十一","description":"<p>6、解脉令人腰痛。痛引肩。目䀮䀮然。时遗溲。刺解脉。在膝筋肉分间外廉之横脉出血。血变而止。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201125,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、解脉令人腰痛。痛引肩。目䀮䀮然。时遗溲。刺解脉。在膝筋肉分间外廉之横脉出血。血变而止。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1O82gxQeQqX', 4, '{"title":"第20201126条・刺腰痛篇第四十一","description":"<p>7、解脉令人腰痛如引带。常如折腰状。善恐。刺解脉，在郄中结络如黍米。刺之血射以黑。见赤血而已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201126,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、解脉令人腰痛如引带。常如折腰状。善恐。刺解脉，在郄中结络如黍米。刺之血射以黑。见赤血而已。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jxsnPPZS5qe', 4, '{"title":"第20201127条・刺腰痛篇第四十一","description":"<p>8、同阴之脉。令人腰痛。痛如小锤居其中。怫然肿。刺同阴之脉。在外踝上绝骨之端。为三痏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201127,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '8、同阴之脉。令人腰痛。痛如小锤居其中。怫然肿。刺同阴之脉。在外踝上绝骨之端。为三痏。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XtZCxwV615B', 4, '{"title":"第20201128条・刺腰痛篇第四十一","description":"<p>9、阳维之脉令人腰痛。痛上怫然肿。刺阳维之脉。脉与太阳合腨下间。去地一尺所。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201128,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '9、阳维之脉令人腰痛。痛上怫然肿。刺阳维之脉。脉与太阳合腨下间。去地一尺所。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2OCUmRQA2wL', 4, '{"title":"第20201129条・刺腰痛篇第四十一","description":"<p>10、衡络之脉令人腰痛。不可以俯仰。仰则恐仆。得之举重伤腰。衡络绝。恶血归之。刺之在郄阳筋之间。上郄数寸。衡居为二痏出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201129,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '10、衡络之脉令人腰痛。不可以俯仰。仰则恐仆。得之举重伤腰。衡络绝。恶血归之。刺之在郄阳筋之间。上郄数寸。衡居为二痏出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WA4QzHb25Io', 4, '{"title":"第20201130条・刺腰痛篇第四十一","description":"<p>11、会阴之脉令人腰痛。痛上漯漯然汗出。汗干令人欲饮。饮已欲走。刺直阳之脉上三痏。在跷上下五寸横居。视其盛者出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201130,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '11、会阴之脉令人腰痛。痛上漯漯然汗出。汗干令人欲饮。饮已欲走。刺直阳之脉上三痏。在跷上下五寸横居。视其盛者出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aeRUXQBLo1M', 4, '{"title":"第20201131条・刺腰痛篇第四十一","description":"<p>12、飞阳之脉令人腰痛。痛上拂拂然。甚则悲以恐。刺飞阳之脉。在内踝上五寸。少阴之前。与阴维之会。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201131,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '12、飞阳之脉令人腰痛。痛上拂拂然。甚则悲以恐。刺飞阳之脉。在内踝上五寸。少阴之前。与阴维之会。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('aBoLkZlvo47', 4, '{"title":"第20201132条・刺腰痛篇第四十一","description":"<p>13、昌阳之脉令人腰痛。痛引膺。目䀮䀮然。甚则反折。舌卷不能言。刺内筋为二痏。在内踝上大筋前太阴后。上踝二寸所。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201132,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、昌阳之脉令人腰痛。痛引膺。目䀮䀮然。甚则反折。舌卷不能言。刺内筋为二痏。在内踝上大筋前太阴后。上踝二寸所。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mWedC6FPp4o', 4, '{"title":"第20201133条・刺腰痛篇第四十一","description":"<p>14、散脉令人腰痛而热。热甚生烦。腰下如有横木居其中。甚则遗溲。刺散脉。在膝前骨肉分间。络外廉。束脉为三痏。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201133,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、散脉令人腰痛而热。热甚生烦。腰下如有横木居其中。甚则遗溲。刺散脉。在膝前骨肉分间。络外廉。束脉为三痏。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2esLIy6Egq2', 4, '{"title":"第20201134条・刺腰痛篇第四十一","description":"<p>15、肉里之脉令人腰痛。不可以咳。咳则筋缩急。刺肉里之脉为二痏。在太阳之外。少阳绝骨之后。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201134,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、肉里之脉令人腰痛。不可以咳。咳则筋缩急。刺肉里之脉为二痏。在太阳之外。少阳绝骨之后。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('s1NFmHlvng5', 4, '{"title":"第20201135条・刺腰痛篇第四十一","description":"<p>16、腰痛侠脊而痛至头几几然。目䀮䀮欲僵仆。刺足太阳郄中出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201135,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、腰痛侠脊而痛至头几几然。目䀮䀮欲僵仆。刺足太阳郄中出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ylONLqvoVFp', 4, '{"title":"第20201136条・刺腰痛篇第四十一","description":"<p>17、腰痛上寒。刺足太阳阳明。上热。刺足厥阴。不可以俯仰。刺足少阳。中热而喘。刺足少阴。刺郄中出血。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201136,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '17、腰痛上寒。刺足太阳阳明。上热。刺足厥阴。不可以俯仰。刺足少阳。中热而喘。刺足少阴。刺郄中出血。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('K18VFBpqr17', 4, '{"title":"第20201137条・刺腰痛篇第四十一","description":"<p>18、腰痛。上寒不可顾。刺足阳明。上热，刺足太阴。中热而喘，刺足少阴。大便难。刺足少阴。 少腹满。刺足厥阴。如折不可以俯仰。不可举。刺足太阳。引脊内廉。刺足少阴。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201137,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '18、腰痛。上寒不可顾。刺足阳明。上热，刺足太阴。中热而喘，刺足少阴。大便难。刺足少阴。 少腹满。刺足厥阴。如折不可以俯仰。不可举。刺足太阳。引脊内廉。刺足少阴。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vvVjH7Ru9BW', 4, '{"title":"第20201138条・刺腰痛篇第四十一","description":"<p>19、腰痛引少腹控䏚。不可以仰。刺腰尻交者。两髁胂上。以月生死为数。发针立已。左取右。右取左。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201138,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、腰痛引少腹控䏚。不可以仰。刺腰尻交者。两髁胂上。以月生死为数。发针立已。左取右。右取左。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'JStqF1yN3x0');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('G1j53z2YrRd', 4, '{"title":"第20201139条・风论篇第四十二","description":"<p>1、黄帝问曰：风之伤人也。或为寒热。或为热中。或为寒中。或为疠风。或为偏枯。或为风也。其病各异。其名不同。或内至五藏六腑。不知其解。愿闻其说。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201139,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '1、黄帝问曰：风之伤人也。或为寒热。或为热中。或为寒中。或为疠风。或为偏枯。或为风也。其病各异。其名不同。或内至五藏六腑。不知其解。愿闻其说。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UcBginLMBQt', 4, '{"title":"第20201140条・风论篇第四十二","description":"<p>2、岐伯对曰：风气藏于皮肤之间。内不得通。外不得泄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201140,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2、岐伯对曰：风气藏于皮肤之间。内不得通。外不得泄。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('E265TqD6tNJ', 4, '{"title":"第20201141条・风论篇第四十二","description":"<p>3、风者善行而数变。腠理开则洒然寒。闭则热而闷。其寒也则衰食饮。其热也则消肌肉。故使人怢栗而不能食。名曰寒热。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201141,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '3、风者善行而数变。腠理开则洒然寒。闭则热而闷。其寒也则衰食饮。其热也则消肌肉。故使人怢栗而不能食。名曰寒热。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cFgNRqahPaa', 4, '{"title":"第20201142条・风论篇第四十二","description":"<p>4、风气与阳明入胃。循脉而上至目内眦。其人肥则风气不得外泄。则为热中而目黄。人瘦则外泄而寒。则为寒中而泣出。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201142,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '4、风气与阳明入胃。循脉而上至目内眦。其人肥则风气不得外泄。则为热中而目黄。人瘦则外泄而寒。则为寒中而泣出。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0CWoUBmf1tR', 4, '{"title":"第20201143条・风论篇第四十二","description":"<p>5、风气与太阳俱入。行诸脉俞。散于分肉之间。与卫气相干。其道不利。故使肌肉愤䐜而有疡。卫气有所凝而不行。故其肉有不仁也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201143,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '5、风气与太阳俱入。行诸脉俞。散于分肉之间。与卫气相干。其道不利。故使肌肉愤䐜而有疡。卫气有所凝而不行。故其肉有不仁也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NyM1RosOyp0', 4, '{"title":"第20201144条・风论篇第四十二","description":"<p>6、疠者。有荣气热。其气不清。故使其鼻柱坏而色败。皮肤疡溃。风寒客于脉而不去。名曰疠风。或名曰寒热。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201144,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '6、疠者。有荣气热。其气不清。故使其鼻柱坏而色败。皮肤疡溃。风寒客于脉而不去。名曰疠风。或名曰寒热。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z4OXWvvIpRV', 4, '{"title":"第20201145条・风论篇第四十二","description":"<p>7、以春甲乙伤于风者为肝风。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201145,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '7、以春甲乙伤于风者为肝风。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
