INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('lVwZ0j4xzf7', 4, '{"title":"第20201161条・风论篇第四十二","description":"<p>23、心风之状。多汗恶风。焦绝善怒吓。赤色。病甚则言不可快。诊在口。其色赤。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201161,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、心风之状。多汗恶风。焦绝善怒吓。赤色。病甚则言不可快。诊在口。其色赤。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i1Iia1M8OYO', 4, '{"title":"第20201162条・风论篇第四十二","description":"<p>24、肝风之状。多汗恶风。善悲。色微苍。嗌干善怒。时憎女子。诊在目下。其色青。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201162,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、肝风之状。多汗恶风。善悲。色微苍。嗌干善怒。时憎女子。诊在目下。其色青。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('H0173b7a7yj', 4, '{"title":"第20201163条・风论篇第四十二","description":"<p>25、脾风之状。多汗恶风。身体怠惰。四肢不欲动。色薄微黄。不嗜食。诊在鼻上。其色黄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201163,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '25、脾风之状。多汗恶风。身体怠惰。四肢不欲动。色薄微黄。不嗜食。诊在鼻上。其色黄。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xjM1dOoQ6cT', 4, '{"title":"第20201164条・风论篇第四十二","description":"<p>26、肾风之状。多汗恶风。面庬然浮肿，脊痛不能正立。其色炲。隐曲不利。诊在肌上。其色黑。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201164,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '26、肾风之状。多汗恶风。面庬然浮肿，脊痛不能正立。其色炲。隐曲不利。诊在肌上。其色黑。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('q1IkxoNS66C', 4, '{"title":"第20201165条・风论篇第四十二","description":"<p>27、胃风之状。颈多汗恶风。食饮不下。膈塞不通。腹善满。失衣则䐜胀。食寒则泄。诊形瘦而腹大。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201165,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '27、胃风之状。颈多汗恶风。食饮不下。膈塞不通。腹善满。失衣则䐜胀。食寒则泄。诊形瘦而腹大。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Xx1atoDbkrX', 4, '{"title":"第20201166条・风论篇第四十二","description":"<p>28、首风之状。头面多汗恶风。当先风一日则病甚。头痛不可以出内。至其风日则病少愈。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201166,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '28、首风之状。头面多汗恶风。当先风一日则病甚。头痛不可以出内。至其风日则病少愈。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nxU5AXkGu90', 4, '{"title":"第20201167条・风论篇第四十二","description":"<p>29、漏风之状。或多汗。常不可单衣。食则汗出。甚则身汗。喘息恶风。衣常濡。口干善渴。不能劳事。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201167,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '29、漏风之状。或多汗。常不可单衣。食则汗出。甚则身汗。喘息恶风。衣常濡。口干善渴。不能劳事。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('76VYpn6onYl', 4, '{"title":"第20201168条・风论篇第四十二","description":"<p>30、泄风之状。多汗。汗出泄衣上。口中干。上渍。其风不能劳事。身体尽痛则寒。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201168,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '30、泄风之状。多汗。汗出泄衣上。口中干。上渍。其风不能劳事。身体尽痛则寒。帝曰：善。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'PLr3OiBxN5B');
