INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0WkZUsqrDLL', 4, '{"title":"第20201181条・痹论篇第四十三","description":"<p>13、所谓痹者。各以其时重感于风寒湿之气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201181,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '13、所谓痹者。各以其时重感于风寒湿之气也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R1Asec37R4K', 4, '{"title":"第20201182条・痹论篇第四十三","description":"<p>14、凡痹之客五藏者。肺痹者。烦满喘而呕。心痹者。脉不通。烦则心下鼓。暴上气而喘。嗌干善噫。厥气上则恐。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201182,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '14、凡痹之客五藏者。肺痹者。烦满喘而呕。心痹者。脉不通。烦则心下鼓。暴上气而喘。嗌干善噫。厥气上则恐。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('C191ZaaLqB6', 4, '{"title":"第20201183条・痹论篇第四十三","description":"<p>15、肝痹者。夜卧则惊。多饮数小便。上为引如怀。肾痹者。善胀。尻以代踵。脊以代头。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201183,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '15、肝痹者。夜卧则惊。多饮数小便。上为引如怀。肾痹者。善胀。尻以代踵。脊以代头。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cqEaduwTtkP', 4, '{"title":"第20201184条・痹论篇第四十三","description":"<p>16、脾痹者。四肢解惰。发咳呕汁。上为大塞。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201184,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '16、脾痹者。四肢解惰。发咳呕汁。上为大塞。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FDUvSxlzFc9', 4, '{"title":"第20201185条・痹论篇第四十三","description":"<p>17、肠痹者。数饮而出不得。中气喘争。时发飧泄。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201185,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '17、肠痹者。数饮而出不得。中气喘争。时发飧泄。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OK0J3KAdKJS', 4, '{"title":"第20201186条・痹论篇第四十三","description":"<p>18、胞痹者。少腹膀胱按之内痛。若沃以汤。涩于小便。上为清涕。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201186,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '18、胞痹者。少腹膀胱按之内痛。若沃以汤。涩于小便。上为清涕。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yO2h4ma6Pij', 4, '{"title":"第20201187条・痹论篇第四十三","description":"<p>19、阴气者。静则神藏。躁则消亡。饮食自倍。肠胃乃伤。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201187,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '19、阴气者。静则神藏。躁则消亡。饮食自倍。肠胃乃伤。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3y02ebg2pf0', 4, '{"title":"第20201188条・痹论篇第四十三","description":"<p>20、淫气喘息。痹聚在肺。淫气忧思。痹聚在心。淫气遗溺。痹聚在肾。淫气乏竭。痹聚在肝。淫气肌绝。痹聚在脾。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201188,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '20、淫气喘息。痹聚在肺。淫气忧思。痹聚在心。淫气遗溺。痹聚在肾。淫气乏竭。痹聚在肝。淫气肌绝。痹聚在脾。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Umwuf9BTD6A', 4, '{"title":"第20201189条・痹论篇第四十三","description":"<p>21、诸痹不已。亦益内也。其风气胜者。其人易已也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201189,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '21、诸痹不已。亦益内也。其风气胜者。其人易已也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VpE4sxbhESl', 4, '{"title":"第20201190条・痹论篇第四十三","description":"<p>22、帝曰：痹。其时有死者。或疼久者。或易已者。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201190,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '22、帝曰：痹。其时有死者。或疼久者。或易已者。其故何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('jqDFeqwRq9X', 4, '{"title":"第20201191条・痹论篇第四十三","description":"<p>23、岐伯曰：其入藏者死。其留连筋骨间者疼久。其留皮肤间者易已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201191,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '23、岐伯曰：其入藏者死。其留连筋骨间者疼久。其留皮肤间者易已。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t310LKsCNKo', 4, '{"title":"第20201192条・痹论篇第四十三","description":"<p>24、帝曰：其客于六腑者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201192,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '24、帝曰：其客于六腑者何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('N80RCWmHraD', 4, '{"title":"第20201193条・痹论篇第四十三","description":"<p>25、岐伯曰：此亦其食饮居处。为其病本也。六腑亦各有俞。风寒湿气中其俞。而食饮应之。循俞而入。各舍其腑也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201193,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '25、岐伯曰：此亦其食饮居处。为其病本也。六腑亦各有俞。风寒湿气中其俞。而食饮应之。循俞而入。各舍其腑也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uefuWlMHAng', 4, '{"title":"第20201194条・痹论篇第四十三","description":"<p>26、帝曰：以针治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201194,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '26、帝曰：以针治之奈何？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YN1CiKBymCR', 4, '{"title":"第20201195条・痹论篇第四十三","description":"<p>27、岐伯曰：五藏有俞。六腑有合。循脉之分。各有所发。各随其过。则病瘳也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201195,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '27、岐伯曰：五藏有俞。六腑有合。循脉之分。各有所发。各随其过。则病瘳也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cTvI2I5cRK2', 4, '{"title":"第20201196条・痹论篇第四十三","description":"<p>28、帝曰：荣卫之气亦令人痹乎？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201196,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '28、帝曰：荣卫之气亦令人痹乎？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('6Jx6vz1Hi4U', 4, '{"title":"第20201197条・痹论篇第四十三","description":"<p>29、岐伯曰：荣者。水谷之精气也。和调于五藏。洒陈于六腑。乃能入于脉也。故循脉上下。贯五藏。络六腑也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201197,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '29、岐伯曰：荣者。水谷之精气也。和调于五藏。洒陈于六腑。乃能入于脉也。故循脉上下。贯五藏。络六腑也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z6UkjBdJrun', 4, '{"title":"第20201198条・痹论篇第四十三","description":"<p>30、卫者。水谷之悍气也。其气慓疾滑利。不能入于脉也。故循皮肤之中。分肉之间。熏于肓膜。散于胸腹。逆其气则病。从其气则愈。不与风寒湿气合。故不为痹。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201198,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '30、卫者。水谷之悍气也。其气慓疾滑利。不能入于脉也。故循皮肤之中。分肉之间。熏于肓膜。散于胸腹。逆其气则病。从其气则愈。不与风寒湿气合。故不为痹。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('zAdj8AGZg7z', 4, '{"title":"第20201199条・痹论篇第四十三","description":"<p>31、帝曰：善。痹或痛。或不痛。或不仁。或寒。或热。或燥。或湿。其故何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201199,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '31、帝曰：善。痹或痛。或不痛。或不仁。或寒。或热。或燥。或湿。其故何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2KOyzeTzfk8', 4, '{"title":"第20201200条・痹论篇第四十三","description":"<p>32、岐伯曰：痛者。寒气多也。有寒故痛也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201200,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '32、岐伯曰：痛者。寒气多也。有寒故痛也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1ZU8M3a2Mfw', 4, '{"title":"第20201201条・痹论篇第四十三","description":"<p>33、其不痛不仁者。病久入深。荣卫之行涩。经络时疏。故不通。皮肤不营。故为不仁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201201,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '33、其不痛不仁者。病久入深。荣卫之行涩。经络时疏。故不通。皮肤不营。故为不仁。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YGIkceXRtcm', 4, '{"title":"第20201202条・痹论篇第四十三","description":"<p>34、其寒者。阳气少。阴气多。与病相益。故寒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201202,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '34、其寒者。阳气少。阴气多。与病相益。故寒也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('nkJ6MX50Scn', 4, '{"title":"第20201203条・痹论篇第四十三","description":"<p>35、其热者。阳气多。阴气少。病气胜阳遭阴。故为痹热。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201203,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '35、其热者。阳气多。阴气少。病气胜阳遭阴。故为痹热。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('vZtGVF7diSc', 4, '{"title":"第20201204条・痹论篇第四十三","description":"<p>36、其多汗而濡者。此其逢湿甚也。阳气少。阴气盛。两气相感。故汗出而濡也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201204,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '36、其多汗而濡者。此其逢湿甚也。阳气少。阴气盛。两气相感。故汗出而濡也。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kZD0UADCoVE', 4, '{"title":"第20201205条・痹论篇第四十三","description":"<p>37、帝曰：夫痹之为病。痛何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201205,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '37、帝曰：夫痹之为病。痛何也？', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5E3M91o4Bud', 4, '{"title":"第20201206条・痹论篇第四十三","description":"<p>38、岐伯曰：痹在于骨则重。在于脉则血凝而不流。在于筋则屈不伸。在于肉则不仁。在于皮则寒。故具此五者。则不痛也。凡痹之类。逢寒则急。逢热则纵。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201206,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '2024-09-26T13:53:14.000Z', '38、岐伯曰：痹在于骨则重。在于脉则血凝而不流。在于筋则屈不伸。在于肉则不仁。在于皮则寒。故具此五者。则不痛也。凡痹之类。逢寒则急。逢热则纵。帝曰：善。', '2024-09-26T13:53:14.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'aON8geCbwwv');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DJcDIlmSuSE', 4, '{"title":"第20201207条・痿论篇第四十四","description":"<p>1、黄帝问曰：五脏使人痿何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201207,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '1、黄帝问曰：五脏使人痿何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('AYfRwdcoxFJ', 4, '{"title":"第20201208条・痿论篇第四十四","description":"<p>2、岐伯对曰：肺主身之皮毛。心主身之血脉。肝主身之筋膜。脾主身之肌肉。肾主身之骨髓。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201208,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2、岐伯对曰：肺主身之皮毛。心主身之血脉。肝主身之筋膜。脾主身之肌肉。肾主身之骨髓。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kzjIPWYicaC', 4, '{"title":"第20201209条・痿论篇第四十四","description":"<p>3、故肺热叶焦。则皮毛虚弱急薄着。则生痿也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201209,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、故肺热叶焦。则皮毛虚弱急薄着。则生痿也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NAvajcTOei2', 4, '{"title":"第20201210条・痿论篇第四十四","description":"<p>4、心气热。则下脉厥而上。上则下脉虚。虚则生脉痿。枢折挈。胫纵而不任地也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201210,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、心气热。则下脉厥而上。上则下脉虚。虚则生脉痿。枢折挈。胫纵而不任地也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('XnC343FsYPU', 4, '{"title":"第20201211条・痿论篇第四十四","description":"<p>5、肝气热。则胆泄口苦筋膜干。筋膜干则筋急而挛。发为筋痿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201211,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、肝气热。则胆泄口苦筋膜干。筋膜干则筋急而挛。发为筋痿。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cGWLJ4zLPRW', 4, '{"title":"第20201212条・痿论篇第四十四","description":"<p>6、脾气热。则胃干而渴。肌肉不仁。发为肉痿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201212,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、脾气热。则胃干而渴。肌肉不仁。发为肉痿。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('3wvrVbfr9So', 4, '{"title":"第20201213条・痿论篇第四十四","description":"<p>7、肾气热。则腰脊不举。骨枯而髓减。发为骨痿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201213,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、肾气热。则腰脊不举。骨枯而髓减。发为骨痿。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZGx2AxpyrN8', 4, '{"title":"第20201214条・痿论篇第四十四","description":"<p>8、帝曰： 何以得之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201214,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '8、帝曰： 何以得之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZTGdMyqqDH2', 4, '{"title":"第20201215条・痿论篇第四十四","description":"<p>9、岐伯曰：肺者。藏之长也。为心之盖也。有所失亡。所求不得。则发肺鸣。鸣则肺热叶焦。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201215,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '9、岐伯曰：肺者。藏之长也。为心之盖也。有所失亡。所求不得。则发肺鸣。鸣则肺热叶焦。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('R490vsehqI9', 4, '{"title":"第20201216条・痿论篇第四十四","description":"<p>10、故曰： 五脏因肺热叶焦。发为痿。此之谓也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201216,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '10、故曰： 五脏因肺热叶焦。发为痿。此之谓也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('dfq6dGxMcR1', 4, '{"title":"第20201217条・痿论篇第四十四","description":"<p>11、悲哀太甚。则胞络绝。胞络绝则阳气内动。发则心下崩数溲血也。故《本病》曰：大经空虚。发为肌痹。传为脉痿。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201217,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '11、悲哀太甚。则胞络绝。胞络绝则阳气内动。发则心下崩数溲血也。故《本病》曰：大经空虚。发为肌痹。传为脉痿。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uzQbqXLHLZF', 4, '{"title":"第20201218条・痿论篇第四十四","description":"<p>12、思想无穷。所愿不得。意淫于外。入房太甚。宗筋弛纵。发为筋痿。及为白淫。故《下经》曰：筋痿者。生于肝使内也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201218,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '12、思想无穷。所愿不得。意淫于外。入房太甚。宗筋弛纵。发为筋痿。及为白淫。故《下经》曰：筋痿者。生于肝使内也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QK3fZh3z7hd', 4, '{"title":"第20201219条・痿论篇第四十四","description":"<p>13、有渐于湿。以水为事。若有所留。居处相湿。肌肉濡渍。痹而不仁。发为肉痿。故《下经》曰：肉痿者，得之湿地也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201219,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '13、有渐于湿。以水为事。若有所留。居处相湿。肌肉濡渍。痹而不仁。发为肉痿。故《下经》曰：肉痿者，得之湿地也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('n8DiOpOtAou', 4, '{"title":"第20201220条・痿论篇第四十四","description":"<p>14、有所远行劳倦。逢大热而渴。渴则阳气内伐。内伐则热舍于肾。肾者水脏也。今水不胜火。则骨枯而髓虚。故足不任身。发为骨痿。故《下经》曰：骨痿者。生于大热也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201220,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '14、有所远行劳倦。逢大热而渴。渴则阳气内伐。内伐则热舍于肾。肾者水脏也。今水不胜火。则骨枯而髓虚。故足不任身。发为骨痿。故《下经》曰：骨痿者。生于大热也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ign16OSKcuI', 4, '{"title":"第20201221条・痿论篇第四十四","description":"<p>15、帝曰：何以别之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201221,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、帝曰：何以别之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('tyGPQwD5VKk', 4, '{"title":"第20201222条・痿论篇第四十四","description":"<p>16、岐伯曰：肺热者色白而毛败。心热者色赤而络脉溢。肝热者色苍而爪枯。脾热者色黄而肉蠕动。肾热者色黑而齿槁。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201222,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、岐伯曰：肺热者色白而毛败。心热者色赤而络脉溢。肝热者色苍而爪枯。脾热者色黄而肉蠕动。肾热者色黑而齿槁。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pQvSBi5kGoz', 4, '{"title":"第20201223条・痿论篇第四十四","description":"<p>17、帝曰：如夫子言可矣。论言治痿者独取阳明何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201223,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '17、帝曰：如夫子言可矣。论言治痿者独取阳明何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Gw1LaDevRpm', 4, '{"title":"第20201224条・痿论篇第四十四","description":"<p>18、岐伯曰：阳明者。五藏六腑之海。主润宗筋。宗筋主束骨而利机关也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201224,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、岐伯曰：阳明者。五藏六腑之海。主润宗筋。宗筋主束骨而利机关也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('EmmrivtQH9Y', 4, '{"title":"第20201225条・痿论篇第四十四","description":"<p>19、冲脉者。经脉之海也。主渗灌溪谷。与阳明合于宗筋。阴阳宗筋之会。会于气街。而阳明为之长。皆属于带脉。而络于督脉。故阳明虚则宗筋纵。带脉不引。故足痿不用也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201225,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '19、冲脉者。经脉之海也。主渗灌溪谷。与阳明合于宗筋。阴阳宗筋之会。会于气街。而阳明为之长。皆属于带脉。而络于督脉。故阳明虚则宗筋纵。带脉不引。故足痿不用也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('TVI4bmqWZkI', 4, '{"title":"第20201226条・痿论篇第四十四","description":"<p>20、帝曰：治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201226,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '20、帝曰：治之奈何？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('0px8ctX5Cks', 4, '{"title":"第20201227条・痿论篇第四十四","description":"<p>21、岐伯曰：各补其荥而通其俞。调其虚实。和其逆顺。筋脉骨肉。各以其时受月。则病已矣。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201227,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '21、岐伯曰：各补其荥而通其俞。调其虚实。和其逆顺。筋脉骨肉。各以其时受月。则病已矣。帝曰：善。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '7kYBWulkUPr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NrRhWC6MjJt', 4, '{"title":"第20201228条・厥论篇第四十五","description":"<p>1、黄帝问曰：厥之寒热者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201228,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '1、黄帝问曰：厥之寒热者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IWoRcCY8ieX', 4, '{"title":"第20201229条・厥论篇第四十五","description":"<p>2、岐伯对曰：阳气衰于下。则为寒厥。阴气衰于下。则为热厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201229,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2、岐伯对曰：阳气衰于下。则为寒厥。阴气衰于下。则为热厥。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('At243rwoXA9', 4, '{"title":"第20201230条・厥论篇第四十五","description":"<p>3、帝曰：热厥之为热也。必起于足下者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201230,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、帝曰：热厥之为热也。必起于足下者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5vyEYqdCDMz', 4, '{"title":"第20201231条・厥论篇第四十五","description":"<p>4、岐伯曰：阳气起于足五指之表。阴脉者集于足下而聚于足心。故阳气胜则足下热也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201231,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、岐伯曰：阳气起于足五指之表。阴脉者集于足下而聚于足心。故阳气胜则足下热也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7kQTqoFEM41', 4, '{"title":"第20201232条・厥论篇第四十五","description":"<p>5、帝曰：寒厥之为寒也。必从五指而上于膝者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201232,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、帝曰：寒厥之为寒也。必从五指而上于膝者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xyN49ztbRLB', 4, '{"title":"第20201233条・厥论篇第四十五","description":"<p>6、岐伯曰：阴气起于五指之里。集于膝下而聚于膝上。故阴气胜则从五指至膝上寒。其寒也。不从外。皆从内也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201233,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、岐伯曰：阴气起于五指之里。集于膝下而聚于膝上。故阴气胜则从五指至膝上寒。其寒也。不从外。皆从内也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hiVVJyKN4KV', 4, '{"title":"第20201234条・厥论篇第四十五","description":"<p>7、帝曰：寒厥何失而然也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201234,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、帝曰：寒厥何失而然也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Vu2hDdDC8U4', 4, '{"title":"第20201235条・厥论篇第四十五","description":"<p>8、岐伯曰：前阴者。宗筋之所聚。太阴阳明之所合也。春夏则阳气多而阴气少。秋冬则阴气盛而阳气衰。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201235,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '8、岐伯曰：前阴者。宗筋之所聚。太阴阳明之所合也。春夏则阳气多而阴气少。秋冬则阴气盛而阳气衰。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CJVsy7cAnA2', 4, '{"title":"第20201236条・厥论篇第四十五","description":"<p>9、此人者质壮。以秋冬夺于所用。下气上争。不能复。精气溢下。邪气因从之而上也。气因于中。阳气衰。不能渗营其经络。阳气日损。阴气独在。故手足为之寒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201236,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '9、此人者质壮。以秋冬夺于所用。下气上争。不能复。精气溢下。邪气因从之而上也。气因于中。阳气衰。不能渗营其经络。阳气日损。阴气独在。故手足为之寒也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('UvDlzEGN42k', 4, '{"title":"第20201237条・厥论篇第四十五","description":"<p>10、帝曰：热厥何如而然也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201237,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '10、帝曰：热厥何如而然也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HMv7ATH17a4', 4, '{"title":"第20201238条・厥论篇第四十五","description":"<p>11、岐伯曰：酒入于胃。则络脉满而经脉虚。脾主为胃行其津液者也。阴气虚则阳气入。阳气入则胃不和。胃不和则精气竭。精气竭则不营其四肢也。此人必数醉若饱以入房。气聚于脾中不得散。酒气与谷气相薄。热盛于中。故热遍于身内。热而溺赤也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201238,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '11、岐伯曰：酒入于胃。则络脉满而经脉虚。脾主为胃行其津液者也。阴气虚则阳气入。阳气入则胃不和。胃不和则精气竭。精气竭则不营其四肢也。此人必数醉若饱以入房。气聚于脾中不得散。酒气与谷气相薄。热盛于中。故热遍于身内。热而溺赤也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PBsixYST8N6', 4, '{"title":"第20201239条・厥论篇第四十五","description":"<p>12、夫酒气盛而慓悍。肾气有衰。阳气独胜。故手足为之热也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201239,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '12、夫酒气盛而慓悍。肾气有衰。阳气独胜。故手足为之热也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('w2gqZn3NaCV', 4, '{"title":"第20201240条・厥论篇第四十五","description":"<p>13、帝曰：厥或令人腹满。或令人暴不知人。或至半日远至一日乃知人者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201240,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '13、帝曰：厥或令人腹满。或令人暴不知人。或至半日远至一日乃知人者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
