INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kp9PDKkNM6R', 4, '{"title":"第20201242条・厥论篇第四十五","description":"<p>15、帝曰：善。愿闻六经脉之厥状病能也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201242,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、帝曰：善。愿闻六经脉之厥状病能也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'T5Vj6G6VzaE');
