INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HueJBhuO7bk', 4, '{"title":"第20201262条・病能论篇第四十六","description":"<p>2、岐伯对曰：诊此者当候胃脉。其脉当沉细。沉细者气逆。逆者人迎甚盛。甚盛则热。人迎者胃脉也。逆而盛。则热聚于胃口而不行。故胃脘为痈也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201262,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2、岐伯对曰：诊此者当候胃脉。其脉当沉细。沉细者气逆。逆者人迎甚盛。甚盛则热。人迎者胃脉也。逆而盛。则热聚于胃口而不行。故胃脘为痈也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('sNU9fyj04Ko', 4, '{"title":"第20201263条・病能论篇第四十六","description":"<p>3、帝曰：善。人有卧而有所不安者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201263,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、帝曰：善。人有卧而有所不安者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Ryj9VDrZH6H', 4, '{"title":"第20201264条・病能论篇第四十六","description":"<p>4、岐伯曰：脏有所伤及。精有所之寄。则安。故人不能悬其病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201264,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、岐伯曰：脏有所伤及。精有所之寄。则安。故人不能悬其病也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FtflU1tVC5I', 4, '{"title":"第20201265条・病能论篇第四十六","description":"<p>5、帝曰：人之不得偃卧者何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201265,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、帝曰：人之不得偃卧者何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZaqK06qWJDF', 4, '{"title":"第20201266条・病能论篇第四十六","description":"<p>6、岐伯曰：肺者脏之盖也。肺气盛则脉大。脉大则不得偃卧。论在《奇恒阴阳》中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201266,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、岐伯曰：肺者脏之盖也。肺气盛则脉大。脉大则不得偃卧。论在《奇恒阴阳》中。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qXKD0A3IEKO', 4, '{"title":"第20201267条・病能论篇第四十六","description":"<p>7、帝曰：有病厥者。诊右脉沉而紧。左脉浮而迟。不然。病主安在？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201267,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、帝曰：有病厥者。诊右脉沉而紧。左脉浮而迟。不然。病主安在？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fiVsbOKfFWw', 4, '{"title":"第20201268条・病能论篇第四十六","description":"<p>8、岐伯曰：冬诊之。右脉固当沉紧。此应四时。左脉浮而迟。此逆四时。在左当主病在肾。颇关在肺。当腰痛也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201268,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '8、岐伯曰：冬诊之。右脉固当沉紧。此应四时。左脉浮而迟。此逆四时。在左当主病在肾。颇关在肺。当腰痛也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('flMbo34xxMT', 4, '{"title":"第20201269条・病能论篇第四十六","description":"<p>9、帝曰：何以言之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201269,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '9、帝曰：何以言之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('z2AoMJXejZL', 4, '{"title":"第20201270条・病能论篇第四十六","description":"<p>10、岐伯曰：少阴脉贯肾络肺。今得肺脉。肾为之病。故肾为腰痛之病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201270,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '10、岐伯曰：少阴脉贯肾络肺。今得肺脉。肾为之病。故肾为腰痛之病也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('73MeTE6QTXR', 4, '{"title":"第20201271条・病能论篇第四十六","description":"<p>11、帝曰：善。有病颈痈者。或石治之。或针灸治之。而皆已。其真安在？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201271,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '11、帝曰：善。有病颈痈者。或石治之。或针灸治之。而皆已。其真安在？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('V2XPx5rYgnn', 4, '{"title":"第20201272条・病能论篇第四十六","description":"<p>12、岐伯曰：此同名异等者也。夫痈气之息者。宜以针开除去之。夫气盛血聚者。宜石而泻之。此所谓同病异治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201272,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '12、岐伯曰：此同名异等者也。夫痈气之息者。宜以针开除去之。夫气盛血聚者。宜石而泻之。此所谓同病异治也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('uuWtXe4pk5r', 4, '{"title":"第20201273条・病能论篇第四十六","description":"<p>13、帝曰：有病怒狂者。此病安生？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201273,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '13、帝曰：有病怒狂者。此病安生？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GCiEf1Mr0bo', 4, '{"title":"第20201274条・病能论篇第四十六","description":"<p>14、岐伯曰：生于阳也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201274,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '14、岐伯曰：生于阳也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
