INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SKnyd7rMqB7', 4, '{"title":"第20201276条・病能论篇第四十六","description":"<p>16、岐伯曰：阳气者。因暴折而难决。故善怒也。病名曰阳厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201276,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、岐伯曰：阳气者。因暴折而难决。故善怒也。病名曰阳厥。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
