INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('MX3b8NKov5l', 4, '{"title":"第20201278条・病能论篇第四十六","description":"<p>18、岐伯曰：阳明者常动。巨阳少阳不动。不动而动大疾。此其候也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201278,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、岐伯曰：阳明者常动。巨阳少阳不动。不动而动大疾。此其候也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZwRR5J3j2sZ', 4, '{"title":"第20201279条・病能论篇第四十六","description":"<p>19、帝曰：治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201279,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '19、帝曰：治之奈何？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ZjfH3DGOnSn', 4, '{"title":"第20201280条・病能论篇第四十六","description":"<p>20、岐伯曰：夺其食即已。夫食入于阴。长气于阳。故夺其食即已。使之服以生铁洛为饮。夫生铁洛者。下气疾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201280,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '20、岐伯曰：夺其食即已。夫食入于阴。长气于阳。故夺其食即已。使之服以生铁洛为饮。夫生铁洛者。下气疾也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('njawdOX71F1', 4, '{"title":"第20201281条・病能论篇第四十六","description":"<p>21、帝曰：善。有病身热解惰。汗出如浴。恶风少气。此为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201281,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '21、帝曰：善。有病身热解惰。汗出如浴。恶风少气。此为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
