INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q7dEUxsVLTO', 4, '{"title":"第20201284条・病能论篇第四十六","description":"<p>24、岐伯曰：以泽泻。术各十分。麋衔五分。合以三指撮为后饭。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201284,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '24、岐伯曰：以泽泻。术各十分。麋衔五分。合以三指撮为后饭。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VUHyacDob3Z', 4, '{"title":"第20201285条・病能论篇第四十六","description":"<p>25、所谓深之细者。其中手如针也。摩之切之。聚者坚也。博者大也。《上经》者。言气之通天也。《下经》者。言病之变化也。《金匮》者。决死生也。《揆度》者。切度之也。《奇恒》者。言奇病也。所谓奇者。使奇病不得以四时死也。恒者。得以四时死也。所谓揆者。方切求之也。言切求其脉理也。度者。得其病处。以四时度之也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201285,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '25、所谓深之细者。其中手如针也。摩之切之。聚者坚也。博者大也。《上经》者。言气之通天也。《下经》者。言病之变化也。《金匮》者。决死生也。《揆度》者。切度之也。《奇恒》者。言奇病也。所谓奇者。使奇病不得以四时死也。恒者。得以四时死也。所谓揆者。方切求之也。言切求其脉理也。度者。得其病处。以四时度之也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '5vyk1R3R4Rn');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('HneOpwCwWAS', 4, '{"title":"第20201286条・奇病论篇第四十七","description":"<p>1、黄帝问曰：人有重身，九月而喑，此为何也？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201286,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '1、黄帝问曰：人有重身，九月而喑，此为何也？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
