INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fQMEpKmLz1Z', 4, '{"title":"第20201289条・奇病论篇第四十七","description":"<p>4、岐伯曰：胞络者系于肾。少阴之脉。贯肾系舌本。故不能言。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201289,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、岐伯曰：胞络者系于肾。少阴之脉。贯肾系舌本。故不能言。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OJDX06trtrO', 4, '{"title":"第20201290条・奇病论篇第四十七","description":"<p>5、帝曰：治之奈何？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201290,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、帝曰：治之奈何？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('femwMvcbF5k', 4, '{"title":"第20201291条・奇病论篇第四十七","description":"<p>6、岐伯曰：无治也。当十月复。《刺法》 曰：无损不足。益有余。以成其疹。然后调之。所谓无损不足者。身羸瘦。无用镵石也。无益其有余者。腹中有形而泄之。泄之则精出而病独擅中。故曰疹成也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201291,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、岐伯曰：无治也。当十月复。《刺法》 曰：无损不足。益有余。以成其疹。然后调之。所谓无损不足者。身羸瘦。无用镵石也。无益其有余者。腹中有形而泄之。泄之则精出而病独擅中。故曰疹成也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ideEFT0J5Ys', 4, '{"title":"第20201292条・奇病论篇第四十七","description":"<p>7、帝曰：病胁下满气逆。二三岁不已。是为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201292,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、帝曰：病胁下满气逆。二三岁不已。是为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WrkeHJhMJ0m', 4, '{"title":"第20201293条・奇病论篇第四十七","description":"<p>8、岐伯曰：病名曰息积。此不妨于食。不可灸刺。积为导引服药。药不能独治也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201293,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '8、岐伯曰：病名曰息积。此不妨于食。不可灸刺。积为导引服药。药不能独治也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('t50a9pteoXc', 4, '{"title":"第20201294条・奇病论篇第四十七","description":"<p>9、帝曰：人有身体髀股䯒皆肿。环脐而痛。是为何病？  岐伯曰：病名曰伏梁。此风根也。其气溢于大肠而着于肓。肓之原在脐下。故环脐而痛也。不可动之。动之为水溺涩之病也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201294,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '9、帝曰：人有身体髀股䯒皆肿。环脐而痛。是为何病？ 岐伯曰：病名曰伏梁。此风根也。其气溢于大肠而着于肓。肓之原在脐下。故环脐而痛也。不可动之。动之为水溺涩之病也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('YgQ3Vb5ZVXM', 4, '{"title":"第20201295条・奇病论篇第四十七","description":"<p>10、帝曰：人有尺脉数甚。筋急而见。此为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201295,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '10、帝曰：人有尺脉数甚。筋急而见。此为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yX8uqAy8Mmw', 4, '{"title":"第20201296条・奇病论篇第四十七","description":"<p>11、岐伯曰：此所谓疹筋。是人腹必急。白色黑色见。则病甚。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201296,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '11、岐伯曰：此所谓疹筋。是人腹必急。白色黑色见。则病甚。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NttjEErU5n2', 4, '{"title":"第20201297条・奇病论篇第四十七","description":"<p>12、帝曰：人有病头痛以数岁不已。此安得之。名为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201297,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '12、帝曰：人有病头痛以数岁不已。此安得之。名为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('fnGkVFmcYVd', 4, '{"title":"第20201298条・奇病论篇第四十七","description":"<p>13、岐伯曰：当有所犯大寒。内至骨髓。髓者以脑为主。脑逆故令头痛。齿亦痛。病名曰厥逆。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201298,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '13、岐伯曰：当有所犯大寒。内至骨髓。髓者以脑为主。脑逆故令头痛。齿亦痛。病名曰厥逆。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QHOvGJp2fal', 4, '{"title":"第20201299条・奇病论篇第四十七","description":"<p>14、帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201299,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '14、帝曰：善。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('GRbQgJ95EXC', 4, '{"title":"第20201300条・奇病论篇第四十七","description":"<p>15、帝曰：有病口甘者。病名为何？何以得之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201300,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、帝曰：有病口甘者。病名为何？何以得之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i9TkUAfVVAR', 4, '{"title":"第20201301条・奇病论篇第四十七","description":"<p>16、岐伯曰：此五气之溢也。名曰脾瘅。夫五味入口。藏于胃。脾为之行其精气。津液在脾。故令人口甘也。此肥美之所发也。此人必数食甘美而多肥也。肥者令人内热。甘者令人中满。故其气上溢。转为消渴。治之以兰。除陈气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201301,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、岐伯曰：此五气之溢也。名曰脾瘅。夫五味入口。藏于胃。脾为之行其精气。津液在脾。故令人口甘也。此肥美之所发也。此人必数食甘美而多肥也。肥者令人内热。甘者令人中满。故其气上溢。转为消渴。治之以兰。除陈气也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('7s2lyi8xDFm', 4, '{"title":"第20201302条・奇病论篇第四十七","description":"<p>17、帝曰：有病口苦。取阳陵泉。口苦者病名为何？何以得之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201302,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '17、帝曰：有病口苦。取阳陵泉。口苦者病名为何？何以得之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('giyM2OIeIlt', 4, '{"title":"第20201303条・奇病论篇第四十七","description":"<p>18、岐伯曰：病名曰胆瘅。 夫肝者。中之将也。取决于胆。咽为之使。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201303,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、岐伯曰：病名曰胆瘅。 夫肝者。中之将也。取决于胆。咽为之使。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4fnIGyjxuNK', 4, '{"title":"第20201304条・奇病论篇第四十七","description":"<p>19、此人者。数谋虑不决。故胆虚气上溢而口为之苦。治之以胆募俞。治在《阴阳十二官相使》中。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201304,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '19、此人者。数谋虑不决。故胆虚气上溢而口为之苦。治之以胆募俞。治在《阴阳十二官相使》中。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QBKYpCaIC5u', 4, '{"title":"第20201305条・奇病论篇第四十七","description":"<p>20、帝曰：有癃者。一日数十溲。此不足也。身热如炭。颈膺如格。人迎躁盛。喘息气逆。此有余也。太阴脉微细如发者。此不足也。其病安在？名为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201305,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '20、帝曰：有癃者。一日数十溲。此不足也。身热如炭。颈膺如格。人迎躁盛。喘息气逆。此有余也。太阴脉微细如发者。此不足也。其病安在？名为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LCvx03Z3d1s', 4, '{"title":"第20201306条・奇病论篇第四十七","description":"<p>21、岐伯曰：病在太阴。其盛在胃。颇在肺。病名曰厥。死不治。此所谓得五有余二不足也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201306,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '21、岐伯曰：病在太阴。其盛在胃。颇在肺。病名曰厥。死不治。此所谓得五有余二不足也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('O8bIxHIJy9x', 4, '{"title":"第20201307条・奇病论篇第四十七","description":"<p>22、帝曰：何谓五有余二不足？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201307,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '22、帝曰：何谓五有余二不足？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('4XPMVUe2DvF', 4, '{"title":"第20201308条・奇病论篇第四十七","description":"<p>23、岐伯曰：所谓五有余者。五病之气有余也。二不足者。亦病气之不足也。今外得五有余。内得二不足。此其身不表不里。亦正死明矣。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201308,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '23、岐伯曰：所谓五有余者。五病之气有余也。二不足者。亦病气之不足也。今外得五有余。内得二不足。此其身不表不里。亦正死明矣。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2atp6iKMtKC', 4, '{"title":"第20201309条・奇病论篇第四十七","description":"<p>24、帝曰：人生而有病颠疾者。病名曰何？安所得之？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201309,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '24、帝曰：人生而有病颠疾者。病名曰何？安所得之？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('SITAcS7aXWw', 4, '{"title":"第20201310条・奇病论篇第四十七","description":"<p>25、岐伯曰：病名为胎病。此得之在母腹中时。其母有所大惊。气上而不下。精气并居。故令子发为颠疾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201310,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '25、岐伯曰：病名为胎病。此得之在母腹中时。其母有所大惊。气上而不下。精气并居。故令子发为颠疾也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NQzRWZ1MZMS', 4, '{"title":"第20201311条・奇病论篇第四十七","description":"<p>26、帝曰：有病庬然如有水状。切其脉大紧。身无痛者。形不瘦。不能食。食少。名为何病？</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201311,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '26、帝曰：有病庬然如有水状。切其脉大紧。身无痛者。形不瘦。不能食。食少。名为何病？', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PtTojJSPiMk', 4, '{"title":"第20201312条・奇病论篇第四十七","description":"<p>27、岐伯曰：病生在肾。名为肾风。肾风而不能食善惊。惊已心气痿者死。帝曰：善。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201312,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '27、岐伯曰：病生在肾。名为肾风。肾风而不能食善惊。惊已心气痿者死。帝曰：善。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TGRZGnwDjRu');
