INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('umxAEE0c6oX', 4, '{"title":"第20201327条・大奇论篇第四十八","description":"<p>15、肾脉小搏沉。为肠澼下血。血温身热者死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201327,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、肾脉小搏沉。为肠澼下血。血温身热者死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('qg7qcR7ZLvk', 4, '{"title":"第20201328条・大奇论篇第四十八","description":"<p>16、心肝澼亦下血。二脏同病者可治。其脉小沉涩为肠澼。其身热者死。热见七日死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201328,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、心肝澼亦下血。二脏同病者可治。其脉小沉涩为肠澼。其身热者死。热见七日死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('WlPmean4cdV', 4, '{"title":"第20201329条・大奇论篇第四十八","description":"<p>17、胃脉沉鼓涩。胃外鼓大。心脉小坚急。皆膈偏枯。男子发左。女子发右。不喑舌转。可治。三十日起。其从者喑。三岁起。年不满二十者。三岁死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201329,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '17、胃脉沉鼓涩。胃外鼓大。心脉小坚急。皆膈偏枯。男子发左。女子发右。不喑舌转。可治。三十日起。其从者喑。三岁起。年不满二十者。三岁死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('2yoTihcn1JR', 4, '{"title":"第20201330条・大奇论篇第四十八","description":"<p>18、脉至而搏。血衄身热者死。脉来悬钩浮为常脉。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201330,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、脉至而搏。血衄身热者死。脉来悬钩浮为常脉。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dliyydlzsil', 4, '{"title":"第20201331条・大奇论篇第四十八","description":"<p>19、脉至如喘。名曰暴厥。暴厥者不知与人言。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201331,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '19、脉至如喘。名曰暴厥。暴厥者不知与人言。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('guloXjl1rFx', 4, '{"title":"第20201332条・大奇论篇第四十八","description":"<p>20、脉至如数。使人暴惊。三四日自已。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201332,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '20、脉至如数。使人暴惊。三四日自已。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('9UX7aEzvgWW', 4, '{"title":"第20201333条・大奇论篇第四十八","description":"<p>21、脉至浮合。浮合如数。一息十至以上。是经气予不足也。微见九十日死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201333,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '21、脉至浮合。浮合如数。一息十至以上。是经气予不足也。微见九十日死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VkmWerYVouo', 4, '{"title":"第20201334条・大奇论篇第四十八","description":"<p>22、脉至如火薪然。是心精之予夺也。草干而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201334,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '22、脉至如火薪然。是心精之予夺也。草干而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VppDNmX4YZj', 4, '{"title":"第20201335条・大奇论篇第四十八","description":"<p>23、脉至如散叶。是肝气予虚也。木叶落而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201335,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '23、脉至如散叶。是肝气予虚也。木叶落而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Y8xwlfHjHGy', 4, '{"title":"第20201336条・大奇论篇第四十八","description":"<p>24、脉至如省客。省客者脉塞而鼓。是肾气予不足也。悬去枣华而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201336,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '24、脉至如省客。省客者脉塞而鼓。是肾气予不足也。悬去枣华而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('8ch8sKAg56f', 4, '{"title":"第20201337条・大奇论篇第四十八","description":"<p>25、脉至如丸泥。是胃精予不足也。榆荚落而死。  脉至如横格。是胆气予不足也。禾熟而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201337,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '25、脉至如丸泥。是胃精予不足也。榆荚落而死。 脉至如横格。是胆气予不足也。禾熟而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('bz1UPgtO8uX', 4, '{"title":"第20201338条・大奇论篇第四十八","description":"<p>26、脉至如弦缕。是胞精予不足也。病善言。下霜而死。不言可治。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201338,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '26、脉至如弦缕。是胞精予不足也。病善言。下霜而死。不言可治。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Nm8lgul7B6w', 4, '{"title":"第20201339条・大奇论篇第四十八","description":"<p>27、脉至如交漆。交漆者左右旁至也。微见三十日死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201339,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '27、脉至如交漆。交漆者左右旁至也。微见三十日死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('xQakkmkneN3', 4, '{"title":"第20201340条・大奇论篇第四十八","description":"<p>28、脉至如涌泉。浮鼓肌中，。阳气予不足也。少气味。韭英而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201340,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '28、脉至如涌泉。浮鼓肌中，。阳气予不足也。少气味。韭英而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mA75znz53Vv', 4, '{"title":"第20201341条・大奇论篇第四十八","description":"<p>29、脉至如颓土之状。按之不得。是肌气予不足也。五色先见黑白。垒发死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201341,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '29、脉至如颓土之状。按之不得。是肌气予不足也。五色先见黑白。垒发死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('wQ3p6qbtWfo', 4, '{"title":"第20201342条・大奇论篇第四十八","description":"<p>30、脉至如悬雍。悬雍者浮揣切之益大。是十二俞之予不足也。水凝而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201342,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '30、脉至如悬雍。悬雍者浮揣切之益大。是十二俞之予不足也。水凝而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('IvZV5nRchYB', 4, '{"title":"第20201343条・大奇论篇第四十八","description":"<p>31、脉至如偃刀。偃刀者浮之小急。按之坚大急。五脏菀熟。寒热独并于肾也。如此其人不得坐。立春而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201343,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '31、脉至如偃刀。偃刀者浮之小急。按之坚大急。五脏菀熟。寒热独并于肾也。如此其人不得坐。立春而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eG2AP7UGOz0', 4, '{"title":"第20201344条・大奇论篇第四十八","description":"<p>32、脉至如丸滑不直手。不直手者按之不可得也。是大肠气予不足也。枣叶生而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201344,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '32、脉至如丸滑不直手。不直手者按之不可得也。是大肠气予不足也。枣叶生而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('rt7tUrNfFY5', 4, '{"title":"第20201345条・大奇论篇第四十八","description":"<p>33、脉至如华者。令人善恐。不欲坐卧。行立常听。是小肠气予不足也。季秋而死。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201345,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '33、脉至如华者。令人善恐。不欲坐卧。行立常听。是小肠气予不足也。季秋而死。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'dY4OW203gDY');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Dj2cr9R7r83', 4, '{"title":"第20201346条・脉解篇第四十九","description":"<p>1、太阳所谓肿腰脽痛者。正月太阳寅。寅太阳也。正月阳气出在上而阴气盛。阳未得自次也。故肿腰脽痛也。病偏虚为跛者。正月阳气冻解地气而出也。所谓偏虚者。冬寒颇有不足者。故偏虚为跛也。所谓强上引背者。阳气大上而争。故强上也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201346,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '1、太阳所谓肿腰脽痛者。正月太阳寅。寅太阳也。正月阳气出在上而阴气盛。阳未得自次也。故肿腰脽痛也。病偏虚为跛者。正月阳气冻解地气而出也。所谓偏虚者。冬寒颇有不足者。故偏虚为跛也。所谓强上引背者。阳气大上而争。故强上也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('T1K4eGkaSLf', 4, '{"title":"第20201347条・脉解篇第四十九","description":"<p>2、所谓耳鸣者。阳气万物盛上而跃。故耳鸣也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201347,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2、所谓耳鸣者。阳气万物盛上而跃。故耳鸣也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('cyGn08jGb2d', 4, '{"title":"第20201348条・脉解篇第四十九","description":"<p>3、所谓甚则狂颠疾者。阳尽在上而阴气从下。下虚上实。故狂颠疾也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201348,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、所谓甚则狂颠疾者。阳尽在上而阴气从下。下虚上实。故狂颠疾也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('FGrkNOXppQW', 4, '{"title":"第20201349条・脉解篇第四十九","description":"<p>4、所谓浮为聋者。皆在气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201349,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、所谓浮为聋者。皆在气也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k1DcKH9Fghg', 4, '{"title":"第20201350条・脉解篇第四十九","description":"<p>5、所谓入中为喑者。阳盛已衰。故为喑也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201350,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、所谓入中为喑者。阳盛已衰。故为喑也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('hqcnQ4uVOM5', 4, '{"title":"第20201351条・脉解篇第四十九","description":"<p>6、内夺而厥。则为喑俳。此肾虚也。少阴不至者。厥也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201351,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、内夺而厥。则为喑俳。此肾虚也。少阴不至者。厥也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CpKG0oPEoUL', 4, '{"title":"第20201352条・脉解篇第四十九","description":"<p>7、少阳所谓心胁痛者。言少阳戌也。戌者心之所表也。九月阳气尽而阴气盛。故心胁痛也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201352,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、少阳所谓心胁痛者。言少阳戌也。戌者心之所表也。九月阳气尽而阴气盛。故心胁痛也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('ImHVtVOiGy2', 4, '{"title":"第20201353条・脉解篇第四十九","description":"<p>8、所谓不可反侧者。阴气藏物也。物藏则不动。故不可反侧也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201353,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '8、所谓不可反侧者。阴气藏物也。物藏则不动。故不可反侧也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('I1geCSfUozj', 4, '{"title":"第20201354条・脉解篇第四十九","description":"<p>9、所谓甚则跃者。九月万物尽衰。草木毕落而堕。则气去阳而之阴。气盛而阳之下长。故谓跃。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201354,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '9、所谓甚则跃者。九月万物尽衰。草木毕落而堕。则气去阳而之阴。气盛而阳之下长。故谓跃。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('pQepGzCJXEs', 4, '{"title":"第20201355条・脉解篇第四十九","description":"<p>10、阳明所谓洒洒振寒者。阳明者午也。五月盛阳之阴也。阳盛而阴气加之。故洒洒振寒也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201355,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '10、阳明所谓洒洒振寒者。阳明者午也。五月盛阳之阴也。阳盛而阴气加之。故洒洒振寒也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iI50W1ZmQT4', 4, '{"title":"第20201356条・脉解篇第四十九","description":"<p>11、所谓胫肿而股不收者。是五月盛阳之阴也。阳者衰于五月。而一阴气上。与阳始争。故胫肿而股不收也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201356,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '11、所谓胫肿而股不收者。是五月盛阳之阴也。阳者衰于五月。而一阴气上。与阳始争。故胫肿而股不收也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('eQrfEME9Y2A', 4, '{"title":"第20201357条・脉解篇第四十九","description":"<p>12、所谓上喘而为水者。阴气下而复上。上则邪客于藏腑间。故为水也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201357,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '12、所谓上喘而为水者。阴气下而复上。上则邪客于藏腑间。故为水也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Q8gaqyjLjIV', 4, '{"title":"第20201358条・脉解篇第四十九","description":"<p>13、所谓胸痛少气者。水气在藏腑也。水者阴气也。阴气在中。故胸痛少气也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201358,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '13、所谓胸痛少气者。水气在藏腑也。水者阴气也。阴气在中。故胸痛少气也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Z2bOk3s1JwY', 4, '{"title":"第20201359条・脉解篇第四十九","description":"<p>14、所谓甚则厥。恶人与火。闻木音则惕然而惊者。阳气与阴气相薄。水火相恶。故惕然而惊也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201359,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '14、所谓甚则厥。恶人与火。闻木音则惕然而惊者。阳气与阴气相薄。水火相恶。故惕然而惊也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('yQMT3hZIHrM', 4, '{"title":"第20201360条・脉解篇第四十九","description":"<p>15、所谓欲独闭户牖而处者。阴阳相薄也。阳尽而阴盛。故欲独闭户牖而居。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201360,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '15、所谓欲独闭户牖而处者。阴阳相薄也。阳尽而阴盛。故欲独闭户牖而居。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('OQeic2m23jK', 4, '{"title":"第20201361条・脉解篇第四十九","description":"<p>16、所谓病至则欲乘高而歌。弃衣而走者。阴阳复争。而外并于阳。故使之弃衣而走也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201361,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '16、所谓病至则欲乘高而歌。弃衣而走者。阴阳复争。而外并于阳。故使之弃衣而走也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('seyjly6UGIc', 4, '{"title":"第20201362条・脉解篇第四十九","description":"<p>17、所谓客孙脉则头痛鼻鼽腹肿者。阳明并于上。上者则其孙络太阴也。故头痛鼻鼽腹肿也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201362,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '17、所谓客孙脉则头痛鼻鼽腹肿者。阳明并于上。上者则其孙络太阴也。故头痛鼻鼽腹肿也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('CicPANyBAiw', 4, '{"title":"第20201363条・脉解篇第四十九","description":"<p>18、太阴所谓病胀者。太阴子也。十一月万物气皆藏于中。故曰病胀。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201363,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '18、太阴所谓病胀者。太阴子也。十一月万物气皆藏于中。故曰病胀。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('LQgKBNphKk2', 4, '{"title":"第20201364条・脉解篇第四十九","description":"<p>19、所谓上走心为噫者。阴盛而上走于阳明。阳明络属心。故曰上走心为噫也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201364,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '19、所谓上走心为噫者。阴盛而上走于阳明。阳明络属心。故曰上走心为噫也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('BXoCkWok8lX', 4, '{"title":"第20201365条・脉解篇第四十九","description":"<p>20、所谓食则呕者。物盛满而上溢。故呕也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201365,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '20、所谓食则呕者。物盛满而上溢。故呕也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('iHu8dwFDmYa', 4, '{"title":"第20201366条・脉解篇第四十九","description":"<p>21、所谓得后与气则快然如衰者。十二月阴气下衰。而阳气且出。故曰得后与气则快然如衰也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201366,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '21、所谓得后与气则快然如衰者。十二月阴气下衰。而阳气且出。故曰得后与气则快然如衰也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('PqDbWusooDs', 4, '{"title":"第20201367条・脉解篇第四十九","description":"<p>22、少阴所谓腰痛者。少阴者肾也。十月万物阳气皆伤。故腰痛也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201367,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '22、少阴所谓腰痛者。少阴者肾也。十月万物阳气皆伤。故腰痛也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('NCz6kmYmOMx', 4, '{"title":"第20201368条・脉解篇第四十九","description":"<p>23、所谓呕咳上气喘者。阴气在下。阳气在上。诸阳气浮。无所根据从。故呕咳上气喘也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201368,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '23、所谓呕咳上气喘者。阴气在下。阳气在上。诸阳气浮。无所根据从。故呕咳上气喘也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('REq1hPtKKFL', 4, '{"title":"第20201369条・脉解篇第四十九","description":"<p>24、所谓邑邑不能久立。久坐起则目䀮䀮无所见者。万物阴阳不定未有主也。秋气始至。微霜始下。而方杀万物。阴阳内夺。故目䀮䀮无所见也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201369,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '24、所谓邑邑不能久立。久坐起则目䀮䀮无所见者。万物阴阳不定未有主也。秋气始至。微霜始下。而方杀万物。阴阳内夺。故目䀮䀮无所见也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('M2HpTBCEZ9i', 4, '{"title":"第20201370条・脉解篇第四十九","description":"<p>25、所谓少气善怒者。阳气不治。阳气不治则阳气不得出。肝气当治而未得。故善怒。善怒者名曰煎厥。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201370,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '25、所谓少气善怒者。阳气不治。阳气不治则阳气不得出。肝气当治而未得。故善怒。善怒者名曰煎厥。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('B5zypkZMQDq', 4, '{"title":"第20201371条・脉解篇第四十九","description":"<p>26、所谓恐如人将捕之者。秋气万物未有毕去。阴气少。阳气入。阴阳相薄。故恐也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201371,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '26、所谓恐如人将捕之者。秋气万物未有毕去。阴气少。阳气入。阴阳相薄。故恐也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('VKthKRz9qus', 4, '{"title":"第20201372条・脉解篇第四十九","description":"<p>27、所谓恶闻食臭者。胃无气。故恶闻食臭也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201372,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '27、所谓恶闻食臭者。胃无气。故恶闻食臭也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('didvP0kyPWK', 4, '{"title":"第20201373条・脉解篇第四十九","description":"<p>28、所谓面黑如地色者。秋气内夺。故变于色也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201373,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '28、所谓面黑如地色者。秋气内夺。故变于色也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('df944l1Cezu', 4, '{"title":"第20201374条・脉解篇第四十九","description":"<p>29、所谓咳则有血者。阳脉伤也。阳气未盛于上而脉满。满则咳。故血见于鼻也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201374,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '29、所谓咳则有血者。阳脉伤也。阳气未盛于上而脉满。满则咳。故血见于鼻也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('1agQ1aLGlQw', 4, '{"title":"第20201375条・脉解篇第四十九","description":"<p>30、厥阴所谓??疝。妇人少腹肿者。厥阴者辰也。三月阳中之阴。邪在中。故曰疝少腹肿也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201375,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '30、厥阴所谓??疝。妇人少腹肿者。厥阴者辰也。三月阳中之阴。邪在中。故曰疝少腹肿也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('kSTszQKf4Hg', 4, '{"title":"第20201376条・脉解篇第四十九","description":"<p>31、所谓腰脊痛不可以俯仰者。三月一振荣华万物。一俯而不仰也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201376,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '31、所谓腰脊痛不可以俯仰者。三月一振荣华万物。一俯而不仰也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DzK3UEhT0Yi', 4, '{"title":"第20201377条・脉解篇第四十九","description":"<p>32、所谓??癃疝肤胀者。曰阴亦盛而脉胀不通。故曰??癃疝也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201377,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '32、所谓??癃疝肤胀者。曰阴亦盛而脉胀不通。故曰??癃疝也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('Zb274wVQn5S', 4, '{"title":"第20201378条・脉解篇第四十九","description":"<p>33、所谓甚则嗌干热中者。阴阳相薄而热。故嗌干也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201378,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '33、所谓甚则嗌干热中者。阴阳相薄而热。故嗌干也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', '2a2rrVJkrVr');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('5Z21vNHHQzZ', 4, '{"title":"第20201379条・刺要论篇第五十","description":"<p>1、黄帝问曰：愿闻刺要。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201379,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '1、黄帝问曰：愿闻刺要。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('k74M9snVeAJ', 4, '{"title":"第20201380条・刺要论篇第五十","description":"<p>2、岐伯对曰：病有浮沉。刺有浅深。各至其理。无过其道。过之则内伤。不及则生外壅。壅则邪从之。浅深不得。反为大贼。内动五脏。后生大病。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201380,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2、岐伯对曰：病有浮沉。刺有浅深。各至其理。无过其道。过之则内伤。不及则生外壅。壅则邪从之。浅深不得。反为大贼。内动五脏。后生大病。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('DNhpXqt9pAW', 4, '{"title":"第20201381条・刺要论篇第五十","description":"<p>3、故曰：病有在毫毛腠理者。有在皮肤者。有在肌肉者。有在脉者。有在筋者。有在骨者。有在髓者。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201381,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、故曰：病有在毫毛腠理者。有在皮肤者。有在肌肉者。有在脉者。有在筋者。有在骨者。有在髓者。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('i5lSur2J3mh', 4, '{"title":"第20201382条・刺要论篇第五十","description":"<p>4、是故刺毫毛腠理无伤皮。皮伤则内动肺。肺动则秋病温疟。溯溯然寒栗。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201382,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '4、是故刺毫毛腠理无伤皮。皮伤则内动肺。肺动则秋病温疟。溯溯然寒栗。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('mn5JGERtMhQ', 4, '{"title":"第20201383条・刺要论篇第五十","description":"<p>5、刺皮无伤肉。肉伤则内动脾。脾动则七十二日四季之月。病腹胀烦不嗜食。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201383,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '5、刺皮无伤肉。肉伤则内动脾。脾动则七十二日四季之月。病腹胀烦不嗜食。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('szGJpNK3dga', 4, '{"title":"第20201384条・刺要论篇第五十","description":"<p>6、刺肉无伤脉。脉伤则内动心。心动则夏病心痛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201384,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '6、刺肉无伤脉。脉伤则内动心。心动则夏病心痛。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('oikWxh7Jyff', 4, '{"title":"第20201385条・刺要论篇第五十","description":"<p>7、刺脉无伤筋。筋伤则内动肝。肝动则春病热而筋弛。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201385,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '7、刺脉无伤筋。筋伤则内动肝。肝动则春病热而筋弛。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'TNTFNgtkhIK');
