INSERT OR REPLACE INTO items (id, status, data, pub_date, created_at, updated_at, content_text, content_text_updated_at, content_text_revision, review_status, book_id, tcm_kind, tcm_parent_id) VALUES ('QL6vNFj1kq2', 4, '{"title":"第20201390条・刺齐论篇第五十一","description":"<p>3、岐伯曰：刺骨无伤筋者。针至筋而去。不及骨也。</p>","content_format":"html","_microfeed":{"bookId":"drsRImTi5tv","receiptNo":20201390,"note":"","videoMemo":"","fangList":[],"bieMing":""}}', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '2024-09-26T13:53:15.000Z', '3、岐伯曰：刺骨无伤筋者。针至筋而去。不及骨也。', '2024-09-26T13:53:15.000Z', 1, NULL, 'drsRImTi5tv', 'section', 'F2ENA9Chce5');
